import json, re
import numpy as np

log_path = "/home/ubuntu/.agent-ml-research-idea_gen_0509_15/projects/vla-ssd/logs/workers/worker_code_threecond_multiseed_r2_v2_analysis_20260518T084856.log"

with open(log_path) as f:
    lines = f.readlines()

all_data = {}

for check_line in range(len(lines)):
    line = lines[check_line].strip()
    if not line:
        continue
    try:
        entry = json.loads(line)
    except:
        continue

    # Check all possible stdout locations
    stdouts = []

    tur = entry.get("tool_use_result", {})
    sc = tur.get("structuredContent", {})
    result_str = sc.get("result", "")
    if result_str:
        try:
            inner = json.loads(result_str)
            stdout = inner.get("data", {}).get("stdout", "")
            if stdout:
                stdouts.append(stdout)
        except:
            pass

    msg = entry.get("message", {})
    for item in msg.get("content", []):
        if item.get("type") == "tool_result":
            raw = item.get("content", "")
            try:
                inner = json.loads(raw)
                if "result" in inner:
                    inner2 = json.loads(inner["result"])
                    stdout = inner2.get("data", {}).get("stdout", "")
                    if stdout:
                        stdouts.append(stdout)
                elif "data" in inner:
                    stdout = inner["data"].get("stdout", "")
                    if stdout:
                        stdouts.append(stdout)
            except:
                pass

    for stdout in stdouts:
        # Parse: "  {cond} L{n}: mean={val} +/- {std} ([s1, s2, s3]) {time}s"
        pattern = r'(untrained|llama2base|trained)\s+L(\d+):\s+mean=([\d.\-]+)\s+\+/-\s+([\d.]+)\s+\(\[([^\]]+)\]\)'
        for m in re.finditer(pattern, stdout):
            cond = m.group(1)
            layer = int(m.group(2))
            seeds_str = m.group(5)
            seeds = [float(x.strip()) for x in seeds_str.split(',')]
            # Compute precise mean and std from seeds
            arr = np.array(seeds)
            mean = float(arr.mean())
            std = float(arr.std())

            if cond not in all_data:
                all_data[cond] = {}
            all_data[cond][layer] = (mean, std, seeds)

# Output the precise arrays for L0-L31
print("# Per-layer R² data from threecond_multiseed_v2 experiment")
print("# 3 seeds (42, 123, 456), sequential 80/20 split, denormalized R² space")
print("# Layers L0-L31 (32 transformer layers)")
print()

for cond in ["trained", "llama2base", "untrained"]:
    means = []
    stds = []
    for i in range(32):
        if i in all_data[cond]:
            mean, std, seeds = all_data[cond][i]
            means.append(round(mean, 10))
            stds.append(round(std, 10))
    print(f"{cond}_mean = {means}")
    print(f"{cond}_std = {stds}")
    print()

# Also output L32 for completeness
print("# L32 (extra layer, likely output projection):")
for cond in ["trained", "llama2base", "untrained"]:
    if 32 in all_data[cond]:
        mean, std, seeds = all_data[cond][32]
        print(f"# {cond} L32: mean={round(mean, 10)}, std={round(std, 10)}, seeds={seeds}")

